'use client';import Link from 'next/link';import {nav,t} from '@/lib/content';import {useLanguage} from './LanguageProvider';
export function Footer(){const{lang}=useLanguage();return <footer className="bg-[#091d18] py-14 text-white"><div className="container grid gap-10 md:grid-cols-[1.5fr_2fr]"><div><div className="mb-4 text-xl font-bold">{t(lang,'საქართველოს სპორტული ორიენტირების ეროვნული ფედერაცია','Georgian National Orienteering Federation')}</div><p className="max-w-md text-sm text-white/60">{t(lang,'ისტორია · სწავლა · აღდგენა · საზოგადოება','History · Learning · Revival · Community')}</p></div><div className="grid grid-cols-2 gap-3 text-sm md:grid-cols-3">{nav.slice(1).map(n=><Link key={n[0]} href={n[0]}>{t(lang,n[1],n[2])}</Link>)}<Link href="/documents">{t(lang,'დოკუმენტები','Documents')}</Link></div></div><div className="container mt-12 border-t border-white/10 pt-6 text-xs text-white/45">© {new Date().getFullYear()} orienteering.ge · Georgia 🇬🇪</div></footer>}
